/**
 * Issue dependencies ("blocked by" links): the completion gate for blocked work and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived, isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";

export type BlockerInput = { orgId: OrgId; issueId: IssueId; blockerId: IssueId };

/** Raised when an issue with open blockers is moved to `done`. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: IssueId,
    readonly blockerIds: readonly IssueId[],
  ) {
    super(`Issue ${issueId} is blocked by ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

export function isOpenBlocker(issue: Issue): boolean {
  return !isArchived(issue) && !isClosedStatus(issue.status);
}

async function loadIssue(orgId: OrgId, issueId: IssueId): Promise<Issue> {
  return requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
}

async function blockerIssues(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const links = await dependencyRepo.listBlockerLinks(orgId, issueId);
  const issues: Issue[] = [];
  for (const link of links) {
    const blocker = await issueRepo.findIssueById(orgId, link.blockerId);
    if (blocker) issues.push(blocker);
  }
  return issues;
}

export async function openBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  return (await blockerIssues(orgId, issueId))
    .filter(isOpenBlocker)
    .map((issue) => issue.id);
}

/** The completion gate every status-changing path runs before writing. */
export async function assertCanTransition(
  orgId: OrgId,
  issueId: IssueId,
  to: IssueStatus,
): Promise<void> {
  if (to !== "done") return;
  const open = await openBlockerIds(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(issueId, open);
}

/** True when `from` can reach `target` by following "blocked by" links. */
async function reaches(
  orgId: OrgId,
  from: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>();
  const stack: IssueId[] = [from];
  while (stack.length > 0) {
    const current = stack.pop()!;
    if (current === target) return true;
    if (seen.has(current)) continue;
    seen.add(current);
    for (const link of await dependencyRepo.listBlockerLinks(orgId, current)) {
      stack.push(link.blockerId);
    }
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  const blocker = await loadIssue(input.orgId, input.blockerId);
  assertCan(actor, "issue:update", issueResource(issue));

  if (issue.id === blocker.id) {
    throw new Error(`Issue ${issue.id} cannot block itself`);
  }
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  // A cycle exists if the blocker is (transitively) blocked by the issue.
  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error(
      `Issue ${blocker.id} already depends on ${issue.id}; link would form a cycle`,
    );
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: BlockerInput,
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = await loadIssue(input.orgId, input.issueId);
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = await loadIssue(orgId, issueId);
  assertCan(actor, "issue:read", issueResource(issue));

  return (await blockerIssues(orgId, issueId))
    .filter((blocker) => !isArchived(blocker))
    .sort((a, b) => a.number - b.number);
}

/** Notifies assignees of issues that `blockerId` closing has fully unblocked. */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const links = await dependencyRepo.listBlockedLinks(orgId, blockerId);
  for (const link of links) {
    const blocked = await issueRepo.findIssueById(orgId, link.issueId);
    if (!blocked || !isOpenBlocker(blocked) || blocked.assigneeId === null) {
      continue;
    }
    if ((await openBlockerIds(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "Your issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
EOF
